package vn.hust.restaurant.repository;
import java.math.*;import java.sql.*;import java.util.*;import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.*;
public class PaymentRepository{
 public int customerPoints(Integer id)throws SQLException{if(id==null)return 0;try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT DiemTichLuy FROM KhachHang WHERE MaKhachHang=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}
 public long finalizeInvoice(InvoicePreview v,int cashierId,List<PaymentPart> parts)throws SQLException{
  if(parts==null||parts.isEmpty())throw new SQLException("Chưa nhập phương thức thanh toán");BigDecimal paid=parts.stream().map(PaymentPart::amount).reduce(BigDecimal.ZERO,BigDecimal::add);if(paid.compareTo(v.total())<0)throw new SQLException("Số tiền thanh toán chưa đủ");
  return Database.inTransaction(c->{
   try(PreparedStatement ck=c.prepareStatement("SELECT TrangThaiPhieu,MaBan FROM PhieuGoiMon WITH(UPDLOCK,HOLDLOCK) WHERE MaPhieu=?")){ck.setLong(1,v.orderId());try(ResultSet r=ck.executeQuery()){if(!r.next())throw new SQLException("Order không tồn tại");if(!List.of("CHO_THANH_TOAN","DANG_PHUC_VU","DA_GUI_BEP").contains(r.getString(1)))throw new SQLException("Order đã được thanh toán hoặc hủy");}}
   try(PreparedStatement ck=c.prepareStatement("SELECT 1 FROM HoaDon WHERE MaPhieu=? AND TrangThaiThanhToan='DA_THANH_TOAN'")){ck.setLong(1,v.orderId());try(ResultSet r=ck.executeQuery()){if(r.next())throw new SQLException("Order đã có hóa đơn");}}
   long id;String code="HD"+System.currentTimeMillis();String method=parts.size()>1?"KET_HOP":parts.get(0).method();String sql="""
    INSERT HoaDon(MaHoaDonCode,MaPhieu,MaKhachHang,MaNhanVienThuNgan,MaKM,NgayGioLap,TyLeVAT,TamTinh,TienGiamKhuyenMai,TienGiamDiem,TongThanhToan,DiemDaDung,DiemTichMoi,HinhThucThanhToan,TienKhachTra,TrangThaiThanhToan)
    OUTPUT INSERTED.MaHoaDon VALUES(?,?,?,?,?,SYSDATETIME(),?,?,?,?,?,?,?,?,?,'DA_THANH_TOAN')
    """;try(PreparedStatement p=c.prepareStatement(sql)){p.setString(1,code);p.setLong(2,v.orderId());Jdbc.nullableInt(p,3,v.customerId());p.setInt(4,cashierId);Jdbc.nullableInt(p,5,v.promotionId());p.setBigDecimal(6,v.vat().divide(v.subtotal().subtract(v.promotionDiscount()).max(BigDecimal.ONE),6,RoundingMode.HALF_UP));p.setBigDecimal(7,v.subtotal());p.setBigDecimal(8,v.promotionDiscount());p.setBigDecimal(9,v.pointDiscount());p.setBigDecimal(10,v.total());p.setInt(11,v.pointsUsed());p.setInt(12,v.pointsEarned());p.setString(13,method);p.setBigDecimal(14,paid);try(ResultSet r=p.executeQuery()){r.next();id=r.getLong(1);}}
   String detail="INSERT ChiTietHoaDon(MaHoaDon,MaMon,SoLuong,DonGiaBan,ThanhTien) SELECT ?,MaMon,SoLuong,DonGiaTaiThoiDiem,SoLuong*DonGiaTaiThoiDiem FROM ChiTietGoiMon WHERE MaPhieu=? AND TrangThaiCheBien<>'DA_HUY'";try(PreparedStatement p=c.prepareStatement(detail)){p.setLong(1,id);p.setLong(2,v.orderId());p.executeUpdate();}
   for(PaymentPart part:parts){try(PreparedStatement p=c.prepareStatement("INSERT ThanhToan(MaHoaDon,PhuongThuc,SoTien,MaGiaoDich,TrangThai,ThoiGian) VALUES(?,?,?,?, 'THANH_CONG',SYSDATETIME())")){p.setLong(1,id);p.setString(2,part.method());p.setBigDecimal(3,part.amount());p.setString(4,part.transactionCode());p.executeUpdate();}}
   if(v.customerId()!=null){try(PreparedStatement p=c.prepareStatement("UPDATE KhachHang SET DiemTichLuy=DiemTichLuy-?+? WHERE MaKhachHang=? AND DiemTichLuy>=?")){p.setInt(1,v.pointsUsed());p.setInt(2,v.pointsEarned());p.setInt(3,v.customerId());p.setInt(4,v.pointsUsed());if(p.executeUpdate()==0)throw new SQLException("Điểm khách hàng không đủ hoặc dữ liệu đã thay đổi");}if(v.pointsUsed()>0)logPoint(c,v.customerId(),id,-v.pointsUsed(),"Đổi điểm khi thanh toán");if(v.pointsEarned()>0)logPoint(c,v.customerId(),id,v.pointsEarned(),"Tích điểm từ hóa đơn");}
   try(PreparedStatement p=c.prepareStatement("UPDATE PhieuGoiMon SET TrangThaiPhieu='DA_THANH_TOAN',ThoiGianKetThuc=SYSDATETIME() WHERE MaPhieu=?")){p.setLong(1,v.orderId());p.executeUpdate();}
   try(PreparedStatement p=c.prepareStatement("UPDATE BanAn SET TrangThai='TRONG' WHERE MaBan=(SELECT MaBan FROM PhieuGoiMon WHERE MaPhieu=?)")){p.setLong(1,v.orderId());p.executeUpdate();}
   return id;
  });
 }
 private void logPoint(Connection c,int customer,long invoice,int delta,String reason)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT LichSuDiem(MaKhachHang,MaHoaDon,DiemThayDoi,LyDo,ThoiGian) VALUES(?,?,?,?,SYSDATETIME())")){p.setInt(1,customer);p.setLong(2,invoice);p.setInt(3,delta);p.setString(4,reason);p.executeUpdate();}}
 public Map<String,Object> invoice(long id)throws SQLException{Map<String,Object>m=new LinkedHashMap<>();String s="SELECT h.MaHoaDonCode,h.NgayGioLap,b.MaBanCode,n.HoTen ThuNgan,kh.HoTen KhachHang,h.TamTinh,h.TienGiamKhuyenMai,h.TienGiamDiem,h.TongThanhToan,h.TienKhachTra FROM HoaDon h JOIN PhieuGoiMon p ON p.MaPhieu=h.MaPhieu JOIN BanAn b ON b.MaBan=p.MaBan JOIN NhanVien n ON n.MaNhanVien=h.MaNhanVienThuNgan LEFT JOIN KhachHang kh ON kh.MaKhachHang=h.MaKhachHang WHERE h.MaHoaDon=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Không tìm thấy hóa đơn");ResultSetMetaData md=r.getMetaData();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));}}return m;}
}
